// ---- Settings ---------------------------------------------------------------
const CONFIG = {
  ollamaUrl: 'http://ollama:11434',
  embedModel: 'bge-m3',   // 1024 dimensions: must match vector(1024) in the schema
  chunkSize: 1200,        // characters per chunk
  chunkOverlap: 200,
  embedBatch: 32,         // chunks per embedding request
};
const PRODUCT_TYPES = ['HM', 'VM', 'PF', 'CO', 'MD'];
const KINDS = ['guideline', 'template', 'reference'];
// -----------------------------------------------------------------------------

const req = $input.first();
const body = req.json.body || {};
const errors = [];
const list = (v) => (Array.isArray(v) ? v : String(v || '').split(',')).map((s) => String(s).trim()).filter(Boolean);

const sourceKey = String(body.sourceKey || '').trim().toLowerCase();
if (!/^[a-z0-9][a-z0-9_.-]{1,80}$/.test(sourceKey)) errors.push('sourceKey is required: a stable id such as "rfda-labelling-guideline" (a-z, 0-9, . _ -)');
const title = String(body.title || '').trim();
if (!title) errors.push('title is required');
const kind = String(body.kind || 'guideline').trim().toLowerCase();
if (!KINDS.includes(kind)) errors.push(`kind must be one of ${KINDS.join(', ')}`);
const productTypes = list(body.productTypes).map((s) => s.toUpperCase());
productTypes.filter((t) => !PRODUCT_TYPES.includes(t)).forEach((t) => errors.push(`Unknown product type "${t}"`));
const requirementIds = list(body.requirementIds).map((s) => s.toLowerCase());
requirementIds.filter((r) => !/^[a-z0-9-]{1,40}$/.test(r)).forEach((r) => errors.push(`Invalid requirement id "${r}"`));
const version = String(body.version || '1').trim().slice(0, 40);

const files = Object.entries(req.binary || {});
if (files.length > 1) errors.push('Send one document per request');
const text = String(body.text || '').trim();
if (!files.length && !text) errors.push('Send a file (field "file") or a "text" field');

const meta = { valid: !errors.length, errors, sourceKey, title, kind, productTypes, requirementIds, version, config: CONFIG };
if (!meta.valid) return [{ json: meta }];

if (files.length) {
  const [, bin] = files[0];
  return [{ json: { ...meta, fileName: bin.fileName || sourceKey }, binary: { data: bin } }];
}
return [{
  json: { ...meta, fileName: sourceKey + '.txt' },
  binary: { data: { data: Buffer.from(text, 'utf8').toString('base64'), mimeType: 'text/plain', fileName: sourceKey + '.txt' } },
}];

function htmlToText(html) {
  return String(html)
    .replace(/<head[\s\S]*?<\/head>/gi, '')
    .replace(/<(script|style)[\s\S]*?<\/\1>/gi, '')
    .replace(/<br\s*\/?>|<\/(p|div|h[1-6]|li|tr)>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&amp;/g, '&')
    .replace(/[ \t]+/g, ' ')
    .replace(/ *\n */g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function chunkText(text, size, overlap) {
  const out = [];
  let start = 0;
  while (start < text.length) {
    let end = Math.min(start + size, text.length);
    if (end < text.length) {
      const brk = Math.max(text.lastIndexOf('\n', end), text.lastIndexOf('. ', end));
      if (brk > start + size * 0.5) end = brk + 1;
    }
    const piece = text.slice(start, end).trim();
    if (piece) out.push(piece);
    if (end >= text.length) break;
    start = Math.max(end - overlap, start + 1);
  }
  return out;
}

// Tika returns XHTML; PDFs come back with one <div class="page"> per page.
function splitPages(html) {
  const parts = String(html).split(/<div class="page">/i);
  if (parts.length > 1) return parts.slice(1).map((p, i) => ({ page: i + 1, text: htmlToText(p) }));
  return [{ page: null, text: htmlToText(html) }];
}

const meta = $('Validate upload').first().json;
const cfg = meta.config;

const chunks = [];
let pages = 0;
for (const { page, text } of splitPages($input.first().json.data || '')) {
  if (page) pages = page;
  for (const piece of chunkText(text, cfg.chunkSize, cfg.chunkOverlap)) chunks.push({ page, chunkIndex: chunks.length, text: piece });
}
if (!chunks.length) throw new Error('No text could be extracted from the document (scanned file without OCR?)');

// One item per batch of chunks, so large documents are embedded in several requests.
const out = [];
for (let i = 0; i < chunks.length; i += cfg.embedBatch) {
  out.push({ json: { model: cfg.embedModel, input: chunks.slice(i, i + cfg.embedBatch).map((c) => c.text), ...(i === 0 ? { chunks, pages } : {}) } });
}
return out;

// Upsert the document by sourceKey and replace all its chunks, in one statement.
const meta = $('Validate upload').first().json;
const { chunks, pages } = $('Split into chunks').first().json;
const vecs = $input.all().flatMap((i) => i.json.embeddings);
if (vecs.length !== chunks.length) throw new Error(`Got ${vecs.length} embeddings for ${chunks.length} chunks`);

const esc = (s) => "'" + String(s).replace(/\u0000/g, '').replace(/'/g, "''") + "'";
const arr = (a) => `ARRAY[${a.map(esc).join(',')}]::text[]`;

const values = chunks.map((c, i) => `(${Number.isInteger(c.page) ? c.page : 'NULL'}, ${c.chunkIndex}, ${esc(c.text)}, '[${vecs[i].join(',')}]')`);
const sql = `WITH doc AS (
  INSERT INTO kb_documents (source_key, title, kind, product_types, requirement_ids, version, file_name, pages, active, updated_at)
  VALUES (${esc(meta.sourceKey)}, ${esc(meta.title)}, ${esc(meta.kind)}, ${arr(meta.productTypes)}, ${arr(meta.requirementIds)}, ${esc(meta.version)}, ${esc(meta.fileName)}, ${pages || 'NULL'}, true, now())
  ON CONFLICT (source_key) DO UPDATE SET title = EXCLUDED.title, kind = EXCLUDED.kind, product_types = EXCLUDED.product_types,
    requirement_ids = EXCLUDED.requirement_ids, version = EXCLUDED.version, file_name = EXCLUDED.file_name, pages = EXCLUDED.pages,
    active = true, updated_at = now()
  RETURNING id, (xmax <> 0) AS replaced
), del AS (
  DELETE FROM kb_chunks WHERE document_id = (SELECT id FROM doc) RETURNING 1
), ins AS (
  INSERT INTO kb_chunks (document_id, page, chunk_index, content, embedding)
  SELECT (SELECT id FROM doc), v.page::int, v.idx::int, v.content, v.emb::vector
  FROM (VALUES ${values.join(',\n  ')}) AS v(page, idx, content, emb)
  RETURNING 1
)
SELECT (SELECT id FROM doc) AS "documentId", (SELECT replaced FROM doc) AS replaced,
       (SELECT count(*) FROM del)::int AS "chunksRemoved", (SELECT count(*) FROM ins)::int AS "chunksStored";`;

return [{ json: { sql } }];

const meta = $('Validate upload').first().json;
const r = $input.first().json;
return [{ json: { body: {
  status: 'stored', documentId: Number(r.documentId), sourceKey: meta.sourceKey, title: meta.title, kind: meta.kind,
  productTypes: meta.productTypes, requirementIds: meta.requirementIds, version: meta.version,
  pages: $('Split into chunks').first().json.pages || null, chunksStored: r.chunksStored, replacedPreviousVersion: r.replaced,
} } }];
